setup:
MUTATE {
  CREATE CONCEPT ?alice { TYPE "Person" NAME "Alice" }
  CREATE CONCEPT ?work { TYPE "Person" NAME "work" }
  ENSURE PROPOSITION ?p_general (?alice, "timezone", "+08:00")
  ENSURE PROPOSITION ?p_work (?alice, "timezone", "+09:00")
  CREATE ASSERTION ?general { SET FIELDS { proposition: ?p_general, asserted_by: ?alice, stance: "support", mode: "stated", asserted_at: "2026-01-01T00:00:00.000Z" } }
  CREATE ASSERTION ?scoped { SET FIELDS { proposition: ?p_work, asserted_by: ?alice, stance: "support", mode: "stated", asserted_at: "2026-01-01T00:00:00.000Z", context_refs: [?work] } }
}

setup.command:
FIND(?alice.id, ?work.id, ?general.id, ?scoped.id) WHERE {
  ?alice CONCEPT {name: "Alice"}
  ?work CONCEPT {name: "work"}
  ?pg PROPOSITION (?alice, "timezone", "+08:00")
  ?pw PROPOSITION (?alice, "timezone", "+09:00")
  ?general ASSERTION {proposition: ?pg}
  ?scoped ASSERTION {proposition: ?pw}
}

cases.command:
MUTATE {
  ASSERT (:alice, "timezone", "+07:00") {
    by: :alice, mode: "stated", at: "2026-09-21T00:00:00.000Z", context: [:work],
    valid: {from: {latest: "2026-01-01T00:00:00.000Z"}}
  } SUPERSEDING :general
}

MUTATE {
  ASSERT (:alice, "timezone", "+07:00") {
    by: :alice, mode: "stated", at: "2026-09-21T00:00:00.000Z",
    valid: {from: {latest: "2026-01-01T00:00:00.000Z"}}
  } SUPERSEDING :scoped
}

MUTATE {
  ASSERT (:alice, "timezone", "+07:00") {
    by: :alice, mode: "stated", at: "2026-09-21T00:00:00.000Z", context: [:work],
    valid: {from: {latest: "2026-01-01T00:00:00.000Z"}}
  } SUPERSEDING :scoped
}
